import { Burst } from '@/components/ui/Burst.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { Badge } from './Badge.js';
import type { MomentCopy } from './copy.js';
import styles from './Takeover.module.css';

/**
 * The big moment, as the Pro sheet does it: confetti, the badge, a title, a
 * line and one button. Its own lazy chunk, loaded only when a takeover
 * fires. Escape, the backdrop and the button all close it; the sheet takes
 * focus and gives it back.
 */
export default function Takeover({
  copy,
  action,
  onClose,
}: {
  copy: MomentCopy;
  /** The button's words: "Lovely", or "Let's go" for the trial. */
  action: string;
  onClose: () => void;
}): React.JSX.Element {
  return (
    <Sheet label={copy.titleText ?? copy.lineText} onClose={onClose}>
      <div className={styles.takeover} data-takeover="">
        <span className={styles.burst} aria-hidden="true">
          <Burst size="takeover" origin="center" />
        </span>
        <Badge icon={copy.icon} />
        <h2 className={styles.title}>{copy.title ?? copy.line}</h2>
        {copy.title !== undefined && <p className={styles.line}>{copy.line}</p>}
        <button type="button" className={styles.done} onClick={onClose}>
          {action}
        </button>
      </div>
    </Sheet>
  );
}
